## 代码实现

### Python

```python
import sys

def solve() -> None:
    data = sys.stdin.buffer.read().split()
    t = int(data[0])
    idx = 1
    out = []

    for _ in range(t):
        R = int(data[idx]); C = int(data[idx + 1])
        idx += 2
        grid = []
        for _ in range(R):
            grid.append(data[idx].decode())
            idx += 1

        # 四个方向：上、下、左、右
        dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        ans = 0

        for i in range(R):
            for j in range(C):
                if grid[i][j] == '#':   # 阻塞格不可操作
                    continue
                deg = 0  # 非阻塞格邻居数量
                for dx, dy in dirs:
                    ni, nj = i + dx, j + dy
                    if 0 <= ni < R and 0 <= nj < C and grid[ni][nj] != '#':
                        deg += 1
                if deg % 2 == 0:         # 邻居数为偶数，异态指标不变
                    ans += 1
        out.append(str(ans))

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    solve()
```

### Java

```java
import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();
        int T = Integer.parseInt(br.readLine().trim());

        // 四个方向：上、下、左、右
        int[] dx = {-1, 1, 0, 0};
        int[] dy = {0, 0, -1, 1};

        while (T-- > 0) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            int R = Integer.parseInt(st.nextToken());
            int C = Integer.parseInt(st.nextToken());
            char[][] grid = new char[R][];
            for (int i = 0; i < R; i++) {
                grid[i] = br.readLine().toCharArray();
            }

            int ans = 0;
            for (int i = 0; i < R; i++) {
                for (int j = 0; j < C; j++) {
                    if (grid[i][j] == '#') {   // 阻塞格不可操作
                        continue;
                    }
                    int deg = 0; // 非阻塞格邻居数量
                    for (int k = 0; k < 4; k++) {
                        int ni = i + dx[k];
                        int nj = j + dy[k];
                        if (ni >= 0 && ni < R && nj >= 0 && nj < C && grid[ni][nj] != '#') {
                            deg++;
                        }
                    }
                    if (deg % 2 == 0) {        // 邻居数为偶数，异态指标不变
                        ans++;
                    }
                }
            }
            sb.append(ans).append('\n');
        }
        System.out.print(sb);
    }
}
```

